import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Input, Alert, api } from '../App';

export default function MappingPage() {
  const [parties,  setParties]  = useState([]);
  const [grades,   setGrades]   = useState([]);   // all grades from catalogue
  const [gardens,  setGardens]  = useState([]);   // all gardens from catalogue
  const [selected, setSelected] = useState(null);
  const [mappedGrades,  setMappedGrades]  = useState([]);
  const [mappedGardens, setMappedGardens] = useState([]);
  const [search,   setSearch]   = useState('');
  const [gSearch,  setGSearch]  = useState('');
  const [saving,   setSaving]   = useState(false);
  const [alert,    setAlert]    = useState(null);
  const [addMode,  setAddMode]  = useState(false);
  const [newParty, setNewParty] = useState({ name:'', code:'', contact:'' });
  const [tab,      setTab]      = useState('gardens'); // 'gardens' or 'grades'

  const load = useCallback(async () => {
    const [p, g, gr] = await Promise.all([
      api.get('/mapping/summary/all').catch(() => ({ data: [] })),
      api.get('/mapping/gardens').catch(() => ({ data: [] })),
      api.get('/marking/grades/list').catch(() => ({ data: [] }))
    ]);
    setParties(p.data);
    setGardens(g.data);
    setGrades(gr.data);
  }, []);

  useEffect(() => { load(); }, [load]);

  const selectParty = async (p) => {
    setSelected(p);
    setAlert(null);
    const r = await api.get(`/mapping/${p.id}`).catch(() => ({ data: [] }));
    setMappedGardens(r.data.map(x => x.garden));
    // Also load grade mappings if we store them
    setMappedGrades([]); // reset grades - could load from separate endpoint
  };

  const toggleGarden = (g) => setMappedGardens(m => m.includes(g) ? m.filter(x => x!==g) : [...m, g]);
  const toggleGrade  = (g) => setMappedGrades(m  => m.includes(g) ? m.filter(x => x!==g) : [...m, g]);

  const save = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      await api.post('/mapping', { party_id: selected.id, gardens: mappedGardens });
      setAlert({ msg:`✅ Saved ${mappedGardens.length} garden mappings for ${selected.party_name}`, type:'success' });
      load();
    } catch (e) {
      setAlert({ msg:'❌ ' + (e.response?.data?.error || e.message), type:'error' });
    } finally { setSaving(false); }
  };

  const addParty = async () => {
    if (!newParty.name || !newParty.code) { setAlert({ msg:'Party name and code required', type:'error' }); return; }
    try {
      await api.post('/parties', { party_name: newParty.name, party_code: newParty.code, contact: newParty.contact });
      setNewParty({ name:'', code:'', contact:'' });
      setAddMode(false);
      load();
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type:'error' });
    }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete party "${name}"? This removes all mappings.`)) return;
    await api.delete(`/parties/${id}`);
    setSelected(null); setMappedGardens([]); setMappedGrades([]);
    load();
  };

  const filteredParties = parties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );
  const filteredGardens = gardens.filter(g => g.toLowerCase().includes(gSearch.toLowerCase()));
  const filteredGrades  = grades.filter(g  => g.toLowerCase().includes(gSearch.toLowerCase()));

  const chipStyle = (selected) => ({
    padding:'5px 12px', borderRadius:20, cursor:'pointer', fontSize:12, fontWeight:600,
    border:`1.5px solid ${selected ? '#1a7a4a' : '#e2e8f0'}`,
    background: selected ? '#dcfce7' : '#f9fafb',
    color: selected ? '#166534' : '#555',
    userSelect:'none', transition:'all 0.1s'
  });

  return (
    <div>
      <h2 style={{ marginBottom:4, color:'#1a3c5e' }}>🔗 Party Mapping</h2>
      <p style={{ color:'#888', fontSize:13, marginBottom:20 }}>Map each party to their gardens and grades from the imported catalogue.</p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display:'flex', gap:16, alignItems:'flex-start' }}>
        {/* LEFT: Party list */}
        <Card style={{ width:280, minWidth:260, flexShrink:0 }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:12 }}>
            <h3 style={{ fontSize:15 }}>Parties ({filteredParties.length})</h3>
            <Button size="sm" onClick={() => setAddMode(!addMode)}>+ Add</Button>
          </div>

          {addMode && (
            <div style={{ background:'#f0f8ff', padding:12, borderRadius:6, marginBottom:12 }}>
              <Input label="Party Name"  value={newParty.name}    onChange={v => setNewParty(p=>({...p,name:v}))}    placeholder="e.g. Sharma & Sons" />
              <Input label="Party Code"  value={newParty.code}    onChange={v => setNewParty(p=>({...p,code:v}))}    placeholder="e.g. SST001" />
              <Input label="Contact"     value={newParty.contact} onChange={v => setNewParty(p=>({...p,contact:v}))} placeholder="Phone/email" />
              <div style={{ display:'flex', gap:8 }}>
                <Button size="sm" variant="success" onClick={addParty}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setAddMode(false)}>Cancel</Button>
              </div>
            </div>
          )}

          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search parties…"
            style={{ width:'100%', padding:'6px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13, marginBottom:8 }} />

          <div style={{ maxHeight:500, overflowY:'auto' }}>
            {filteredParties.length === 0 && (
              <div style={{ color:'#aaa', fontSize:13, padding:12, textAlign:'center' }}>
                {parties.length === 0 ? 'No parties yet. Click + Add to create one.' : 'No parties match search.'}
              </div>
            )}
            {filteredParties.map(p => (
              <div key={p.id}
                onClick={() => selectParty(p)}
                style={{ padding:'8px 10px', borderRadius:6, cursor:'pointer', marginBottom:4,
                  background: selected?.id===p.id ? '#dbeafe' : '#f9fafb',
                  border: selected?.id===p.id ? '1.5px solid #93c5fd' : '1.5px solid transparent',
                  display:'flex', justifyContent:'space-between', alignItems:'flex-start' }}>
                <div>
                  <div style={{ fontWeight:600, fontSize:13 }}>{p.party_name}</div>
                  <div style={{ fontSize:11, color:'#888' }}>{p.party_code} · {p.garden_count} gardens</div>
                </div>
                <button onClick={e => { e.stopPropagation(); delParty(p.id, p.party_name); }}
                  style={{ background:'none', border:'none', cursor:'pointer', color:'#ccc', fontSize:13 }} title="Delete">✕</button>
              </div>
            ))}
          </div>
        </Card>

        {/* RIGHT: Garden/Grade selection */}
        <div style={{ flex:1 }}>
          {!selected ? (
            <Card style={{ textAlign:'center', padding:40, color:'#aaa' }}>
              Select a party from the left to manage their mappings
            </Card>
          ) : (
            <Card>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14 }}>
                <div>
                  <h3 style={{ fontSize:16 }}>{selected.party_name}</h3>
                  <div style={{ fontSize:12, color:'#888' }}>{selected.party_code} · {mappedGardens.length} gardens mapped</div>
                </div>
                <div style={{ display:'flex', gap:8 }}>
                  <Button size="sm" variant="outline" onClick={() => setMappedGardens(tab==='gardens'?[...filteredGardens]:mappedGardens)}>Select All</Button>
                  <Button size="sm" variant="outline" onClick={() => tab==='gardens'?setMappedGardens([]):setMappedGrades([])}>Clear</Button>
                  <Button size="sm" variant="success" onClick={save} disabled={saving}>{saving ? 'Saving…' : `💾 Save`}</Button>
                </div>
              </div>

              {/* Tabs */}
              <div style={{ display:'flex', borderBottom:'2px solid #e2e8f0', marginBottom:12 }}>
                {['gardens','grades'].map(t => (
                  <div key={t} onClick={() => setTab(t)}
                    style={{ padding:'7px 16px', cursor:'pointer', fontSize:13, fontWeight:600,
                      color: tab===t ? '#1a3c5e' : '#888',
                      borderBottom: tab===t ? '2px solid #1a3c5e' : '2px solid transparent',
                      marginBottom:-2 }}>
                    {t === 'gardens' ? `🌿 Gardens (${mappedGardens.length} selected)` : `📊 Grades (${mappedGrades.length} selected)`}
                  </div>
                ))}
              </div>

              <input value={gSearch} onChange={e => setGSearch(e.target.value)}
                placeholder={tab==='gardens' ? 'Search gardens…' : 'Search grades…'}
                style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #e2e8f0', borderRadius:6, fontSize:13, marginBottom:12 }} />

              {tab === 'gardens' && (
                <div style={{ display:'flex', gap:7, flexWrap:'wrap', maxHeight:380, overflowY:'auto' }}>
                  {filteredGardens.length === 0
                    ? <div style={{ color:'#aaa', fontSize:13, padding:12 }}>No gardens found. Import a Catalogue first.</div>
                    : filteredGardens.map(g => (
                      <div key={g} onClick={() => toggleGarden(g)} style={chipStyle(mappedGardens.includes(g))}>
                        {mappedGardens.includes(g) ? '✓ ' : ''}{g}
                      </div>
                    ))
                  }
                </div>
              )}

              {tab === 'grades' && (
                <div style={{ display:'flex', gap:7, flexWrap:'wrap' }}>
                  {filteredGrades.length === 0
                    ? <div style={{ color:'#aaa', fontSize:13, padding:12 }}>No grades found. Import a Catalogue first.</div>
                    : filteredGrades.map(g => (
                      <div key={g} onClick={() => toggleGrade(g)} style={{...chipStyle(mappedGrades.includes(g)), background: mappedGrades.includes(g)?'#dbeafe':'#f9fafb', border:`1.5px solid ${mappedGrades.includes(g)?'#3b82f6':'#e2e8f0'}`, color: mappedGrades.includes(g)?'#1e40af':'#555' }}>
                        {mappedGrades.includes(g) ? '✓ ' : ''}{g}
                      </div>
                    ))
                  }
                </div>
              )}

              {/* Selected summary */}
              {mappedGardens.length > 0 && (
                <div style={{ marginTop:14, padding:10, background:'#f0f8ff', borderRadius:6 }}>
                  <div style={{ fontSize:12, fontWeight:600, color:'#1a3c5e', marginBottom:4 }}>Mapped Gardens ({mappedGardens.length}):</div>
                  <div style={{ fontSize:11, color:'#555', lineHeight:1.8 }}>{mappedGardens.sort().join(' · ')}</div>
                </div>
              )}
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}
